CREATE TABLE users (id BIGINT PRIMARY KEY AUTO_INCREMENT, full_name VARCHAR(120) NOT NULL, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, phone VARCHAR(30), role VARCHAR(20) NOT NULL DEFAULT 'CUSTOMER', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE vehicles (id BIGINT PRIMARY KEY AUTO_INCREMENT, owner_id BIGINT NOT NULL, registration_number VARCHAR(20) NOT NULL UNIQUE, make VARCHAR(80) NOT NULL, model VARCHAR(80) NOT NULL, vehicle_year INT NOT NULL, fuel_type VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_vehicle_owner FOREIGN KEY(owner_id) REFERENCES users(id));
CREATE TABLE services (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(120) NOT NULL UNIQUE, description VARCHAR(1000) NOT NULL, price DECIMAL(10,2) NOT NULL, estimated_duration_minutes INT NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE bookings (id BIGINT PRIMARY KEY AUTO_INCREMENT, customer_id BIGINT NOT NULL, vehicle_id BIGINT NOT NULL, service_id BIGINT NOT NULL, appointment_date_time TIMESTAMP NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', customer_notes VARCHAR(1000), admin_notes VARCHAR(1000), created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, CONSTRAINT fk_booking_customer FOREIGN KEY(customer_id) REFERENCES users(id), CONSTRAINT fk_booking_vehicle FOREIGN KEY(vehicle_id) REFERENCES vehicles(id), CONSTRAINT fk_booking_service FOREIGN KEY(service_id) REFERENCES services(id));
CREATE INDEX ix_booking_time_status ON bookings(appointment_date_time,status); CREATE INDEX ix_booking_customer ON bookings(customer_id); CREATE INDEX ix_vehicle_owner ON vehicles(owner_id);
